  for (let i = 0; i < arr.length; i += 1) {
    const p = arr[i];
    const a = clamp(p.life / p.max, 0, 1);
    ctx.fillStyle = rgba(p.color, a * 0.9);
    const size = p.size * (0.35 + 0.65 * a);
    ctx.fillRect(p.x - size / 2, p.y - size / 2, size, size);
  }
  ctx.restore();
}

